export const HEROES=[
 {id:'vampire',name:'리시엔',race:'뱀파이어',role:'혈월의 귀족',sigil:'리',color:'#bd758f',hp:112,bp:40,mp:38,atk:22,mag:25,def:6,spd:19,weapon:'가문의 레이피어',armor:'벨벳 예복',bio:'베르몽 궁정의 서자. 혈정석 공급권을 되찾으라는 밀명을 받았지만, 계약서 아래 지워진 마을 사람들의 이름을 외면하지 못한다.'},
 {id:'wolf',name:'볼프',race:'늑대인간',role:'철랑의 장교',sigil:'볼',color:'#9caeaa',hp:155,bp:58,mp:27,atk:29,mag:12,def:10,spd:13,weapon:'군용 대검',armor:'강철 장교복',bio:'아이젠볼프 군단의 대위. 광산 봉쇄 명령을 수행하러 왔다. 그러나 광부를 버리라는 명령이 군인의 명예인지 의심하기 시작한다.'},
 {id:'human',name:'에다',race:'인간',role:'룬 기공사',sigil:'에',color:'#d7b576',hp:104,bp:34,mp:52,atk:18,mag:31,def:5,spd:16,weapon:'룬 캐스터',armor:'기공사의 코트',bio:'루멘 자유도시의 견습 기공사. 자신이 설계한 안정화 장치가 폭주의 원인으로 지목되자, 스승이 숨긴 운전 기록을 찾아 나선다.'}
];
export function newGame(){return {version:1,phase:'explore',chapter:0,choice:null,gold:180,shards:5,potions:5,affinity:{vampire:0,wolf:0,human:0},party:HEROES.map(h=>({...h,maxHp:h.hp,maxBp:h.bp,maxMp:h.mp,level:1,xp:0,upgrade:0,armorUpgrade:0,loadout:0,ap:0,guard:false})),enemies:[],active:null,target:0,clock:0,battle:0,log:[],ending:false};}
export const totalAtk=h=>h.atk+h.upgrade*4+(h.loadout?7:0);
export const totalSpd=h=>h.spd-(h.loadout?3:0);
export const totalBp=h=>h.maxBp+h.armorUpgrade*8;
export function skills(h){return [
 {id:'attack',name:'기본 공격',cost:0,tip:'배리어부터 피해 · MP 3 회복'},
 h.id==='vampire'?{id:'skill',name:'혈월 찌르기',cost:9,tip:'배리어 관통 · 준 HP 피해의 40% 흡혈'}:h.id==='wolf'?{id:'skill',name:'강철 파쇄',cost:8,tip:'배리어에 2.6배 피해 · 파괴 시 행동 지연'}:{id:'skill',name:'룬 과부하',cost:10,tip:'적 전체 마법 피해 · 적의 행동 게이지 감소'},
 h.id==='vampire'?{id:'support',name:'붉은 서약',cost:12,tip:'아군 전체 배리어 20 회복'}:h.id==='wolf'?{id:'support',name:'군단의 포효',cost:10,tip:'아군 전체 배리어 16 회복 · 자신 방어'}:{id:'support',name:'수복 술식',cost:12,tip:'가장 위급한 동료 HP 48 회복 · 전투불능 소생'},
 {id:'guard',name:'방어',cost:0,tip:'다음 피격 피해 50% 감소 · BP 15 회복'},
 {id:'potion',name:'회복약',cost:0,tip:'가장 위급한 동료 HP 45 회복 · 소생 가능'}
 ];}
export function log(s,t){s.log.unshift(t);s.log=s.log.slice(0,30);}
export function startBattle(s,battle=1){s.battle=battle;s.phase='battle';s.active=null;s.target=0;s.clock=0;s.enemies=battle===1?[
 {id:'e0',name:'폭주한 파수기',sigil:'Ⅰ',hp:90,maxHp:90,bp:35,maxBp:35,atk:22,def:4,spd:11,ap:12},
 {id:'e1',name:'균열의 잔향',sigil:'Ⅱ',hp:70,maxHp:70,bp:22,maxBp:22,atk:20,def:3,spd:14,ap:0}]:[
 {id:'e0',name:'재의 종지기',sigil:'왕',hp:275,maxHp:275,bp:95,maxBp:95,atk:32,def:8,spd:15,ap:5,boss:true},
 {id:'e1',name:'혈정석 파수기',sigil:'Ⅱ',hp:98,maxHp:98,bp:36,maxBp:36,atk:23,def:4,spd:11,ap:0}];
 s.party.forEach((h,i)=>{h.ap=55-i*12;h.guard=false;});log(s,battle===1?'동력로의 파수기가 폭주했다.':'봉인 안에서 재의 종지기가 깨어났다.');}
export function damage(target,raw,{pierce=false,breaker=false}={}){let amount=Math.max(1,Math.round(raw));if(target.guard){amount=Math.round(amount*.5);target.guard=false;}const before=target.bp;let shield=0,health=0;if(!pierce&&target.bp>0){shield=Math.min(target.bp,breaker?Math.round(amount*2.6):amount);target.bp-=shield;if(!breaker)health=Math.max(0,amount-shield);}else health=amount;target.hp=Math.max(0,target.hp-health);const broken=before>0&&target.bp===0;if(broken)target.ap=Math.max(0,target.ap-28);return {hp:health,bp:shield,broken};}
export function tick(s,dt){if(s.phase!=='battle'||s.active!==null)return [];const events=[];s.clock+=dt;for(const h of s.party)if(h.hp>0){h.ap=Math.min(100,h.ap+totalSpd(h)*dt*1.5);h.bp=Math.min(totalBp(h),h.bp+dt*.7);}for(let i=0;i<s.party.length;i++)if(s.party[i].hp>0&&s.party[i].ap>=100){s.active=i;return [{type:'ready',actor:i}];}for(const e of s.enemies){if(e.hp<=0)continue;e.ap+=e.spd*dt*1.5;if(e.ap>=100){e.ap=0;const alive=s.party.filter(h=>h.hp>0);if(!alive.length)break;const target=alive[Math.floor(s.clock*7+e.atk)%alive.length];const d=damage(target,e.atk-target.def);events.push({type:'hit',actor:e.id,target:target.id,...d});log(s,`${e.name} → ${target.name}: HP ${d.hp} / BP ${d.bp}`);}}if(s.party.every(h=>h.hp<=0)){s.phase='defeat';s.active=null;events.push({type:'defeat'});}return events;}
export function action(s,id){if(s.phase!=='battle'||s.active===null)return {ok:false,reason:'행동 게이지가 찬 동료를 기다려 주세요.'};const h=s.party[s.active],sk=skills(h).find(x=>x.id===id);if(!sk)return {ok:false,reason:'알 수 없는 행동입니다.'};if(h.mp<sk.cost)return {ok:false,reason:'마력이 부족합니다.'};if(id==='potion'&&s.potions<1)return {ok:false,reason:'회복약이 없습니다.'};const events=[];h.mp-=sk.cost;
 const hit=(e,raw,opts={})=>{const d=damage(e,raw,opts);events.push({type:'hit',actor:h.id,target:e.id,...d});log(s,`${h.name} · ${sk.name} → ${e.name}: HP ${d.hp} / BP ${d.bp}${d.broken?' · 배리어 파괴!':''}`);return d;};
 const weakest=()=>s.party.slice().sort((a,b)=>a.hp/a.maxHp-b.hp/b.maxHp)[0];
 if(id==='guard'){h.guard=true;h.bp=Math.min(totalBp(h),h.bp+15);events.push({type:'heal',target:h.id,text:'방어'});}
 else if(id==='potion'){s.potions--;const t=weakest();t.hp=Math.min(t.maxHp,t.hp+45);events.push({type:'heal',target:t.id,text:'+45 HP'});}
 else if(id==='support'){if(h.id==='human'){const t=weakest();t.hp=Math.min(t.maxHp,t.hp+48);events.push({type:'heal',target:t.id,text:'+48 HP'});}else{s.party.filter(t=>t.hp>0).forEach(t=>{t.bp=Math.min(totalBp(t),t.bp+(h.id==='wolf'?16:20));events.push({type:'heal',target:t.id,text:'배리어 회복'});});if(h.id==='wolf')h.guard=true;}}
 else{let e=s.enemies[s.target];if(!e||e.hp<=0)e=s.enemies.find(e=>e.hp>0);if(id==='attack'){hit(e,totalAtk(h)-e.def);h.mp=Math.min(h.maxMp,h.mp+3);}else if(h.id==='vampire'){const d=hit(e,h.mag+totalAtk(h)*.6,{pierce:true});h.hp=Math.min(h.maxHp,h.hp+Math.round(d.hp*.4));}else if(h.id==='wolf'){hit(e,totalAtk(h)+8,{breaker:true});}else{s.enemies.filter(e=>e.hp>0).forEach(e=>{hit(e,h.mag*1.25+h.upgrade*3);e.ap=Math.max(0,e.ap-15);});}}
 h.ap=0;s.active=null;log(s,`${h.name}: ${sk.name}`);if(s.enemies.every(e=>e.hp<=0)){s.phase='victory';events.push({type:'victory'});}return {ok:true,events};}
export function reward(s){if(s.phase!=='victory')return false;const boss=s.battle===2;s.gold+=boss?220:120;s.shards+=boss?6:4;s.potions+=2;for(const h of s.party){h.xp+=boss?150:100;while(h.xp>=h.level*80){h.xp-=h.level*80;h.level++;h.maxHp+=16;h.maxBp+=5;h.maxMp+=5;h.atk+=3;h.mag+=3;h.def++;h.spd++;}h.hp=h.maxHp;h.bp=totalBp(h);h.mp=h.maxMp;}s.chapter=boss?3:2;s.phase='explore';s.ending=boss;s.enemies=[];log(s,boss?'재의 종지기를 진정시키고 진실의 기록을 확보했다.':'첫 전투 승리. 동료들의 레벨이 올랐다.');return true;}
export function enhance(s,index,slot='weapon'){if(s.phase!=='explore')return {ok:false,reason:'탐색 중에만 강화할 수 있습니다.'};const h=s.party[index];if(!h||!['weapon','armor'].includes(slot))return {ok:false,reason:'잘못된 장비입니다.'};const key=slot==='weapon'?'upgrade':'armorUpgrade',level=h[key],cost=50+level*40,shards=2+level;if(level>=3)return {ok:false,reason:'프로토타입에서는 +3까지 강화할 수 있습니다.'};if(s.gold<cost||s.shards<shards)return {ok:false,reason:'은화 또는 혈정석이 부족합니다.'};s.gold-=cost;s.shards-=shards;h[key]++;if(slot==='armor')h.bp=Math.min(totalBp(h),h.bp+8);log(s,`${h.name}: ${slot==='weapon'?h.weapon:h.armor} +${h[key]} 강화`);return {ok:true};}
export function rest(s){if(s.phase!=='explore')return false;s.party.forEach(h=>{h.hp=h.maxHp;h.bp=totalBp(h);h.mp=h.maxMp;});return true;}
export function choose(s,choice){if(s.chapter!==0||!['vampire','wolf','human'].includes(choice))return false;s.choice=choice;s.affinity[choice]+=1;s.chapter=1;if(choice==='human')s.potions+=2;if(choice==='wolf')s.party.forEach(h=>{h.maxBp+=8;h.bp+=8;});if(choice==='vampire')s.gold+=60;return true;}
export function serialize(s){return JSON.stringify(s);}
export function restore(raw){try{const s=JSON.parse(raw);if(s.version!==1||s.phase!=='explore'||!Array.isArray(s.party)||s.party.length!==3||!Number.isInteger(s.chapter)||s.chapter<0||s.chapter>3||!['gold','shards','potions'].every(k=>Number.isFinite(s[k])&&s[k]>=0))return null;for(let i=0;i<3;i++){const h=s.party[i];if(h.id!==HEROES[i].id||!['hp','bp','mp','maxHp','maxBp','maxMp','atk','mag','def','spd','level','xp','upgrade','armorUpgrade','loadout'].every(k=>Number.isFinite(h[k])&&h[k]>=0)||h.level<1||h.level>99||h.maxHp<=0||h.maxMp<=0||h.upgrade>3||h.armorUpgrade>3||h.loadout>1)return null;h.hp=Math.min(h.hp,h.maxHp);h.bp=Math.min(h.bp,totalBp(h));h.mp=Math.min(h.mp,h.maxMp);}if(!s.affinity||!['vampire','wolf','human'].every(k=>Number.isFinite(s.affinity[k])))return null;s.log=Array.isArray(s.log)?s.log.filter(x=>typeof x==='string').slice(0,30):[];s.enemies=[];s.active=null;return s;}catch{return null;}}
